304			t.Fatal("expected corrupt error")
305		} else {
306			var ec errCorrupt
307			if !errors.As(err, &ec) {
308				t.Fatalf("character-corrupt archive -> expected errCorrupt, got %T: %v", err, err)
309			}
310		}
311		missing := strings.Repeat("0", 64)
312		if _, err := LoadReport(dir, missing); err == nil {
313			t.Fatal("expected not found error")
314		} else {
315			var enf errNotFound
316			if !errors.As(err, &enf) {
317				t.Fatalf("missing report -> expected errNotFound, got %T: %v", err, err)
318			}
319		}
320		if _, err := LoadReport(dir, "xyz"); err == nil {
321			t.Fatal("expected invalid id error")
322		} else {
323			var ei errInvalid
324			if !errors.As(err, &ei) {
