330	// --- diff：同一归档被用作任意一侧都拒绝整次比较，不输出已读成功一侧 ---
331	
332	func TestDiffStoreRejectsCharacterCorruptionOnEitherSide(t *testing.T) {
333		dir := t.TempDir()
334		goodID := writeReportWithFreshID(t, dir, oneDefectFixture())
335		// 另一侧是另一份合法报告（规则集合不同，标识不同），落盘文本再注入字符
336		// 问题；改写后的标识与内容仍然相符。
337		badID := writeVariantArchiveText(t, dir, oneRuleCharReport("反例：�重入"),
338			func(doc string) string {
339				return strings.ReplaceAll(doc, string(replacementCharBytes), `\uD800`)
340			})
341		if badID == goodID {
342			t.Fatal("test setup: the two reports must have distinct ids")
343		}
344	
345		for _, tc := range []struct {
346			name   string
347			before string
348			after  string
349		}{
350			{"second report corrupt", goodID, badID},
351			{"first report corrupt", badID, goodID},
352		} {
353			t.Run(tc.name, func(t *testing.T) {
354				diff, err := DiffStore(dir, tc.before, tc.after)
355				if err == nil {
356					t.Fatalf("diff must fail when a side is character-corrupt, got %+v", diff)
357				}
358				var ec errCorrupt
359				if !errors.As(err, &ec) {
360					t.Fatalf("expected errCorrupt, got %T: %v", err, err)
361				}
362				if !reflect.DeepEqual(diff, DiffResult{}) {
363					t.Fatalf("failed diff must return the zero result, got %+v", diff)
364				}
365				if !strings.Contains(err.Error(), badID) {
366					t.Fatalf("error must name the corrupt side %q: %v", badID, err)
367				}
368				if !strings.Contains(err.Error(), "surrogate") {
369					t.Fatalf("error must classify the character problem: %v", err)
370				}
371			})
372		}
373	}
374	
375	// --- audit 保存遇到同标识既有字符损坏归档：不能视为保存成功，原文件保留 ---
376	
377	func TestSaveReportCharacterCorruptExistingArchiveNotTreatedAsSaved(t *testing.T) {
378		dir := t.TempDir()
379		r := oneRuleCharReport("反例：�重入")
380		id := writeVariantArchiveText(t, dir, r, func(doc string) string {
381			return strings.ReplaceAll(doc, string(replacementCharBytes), `\uD800`)
382		})
383		path := filepath.Join(dir, id+".json")
384		before, err := os.ReadFile(path)
385		if err != nil {
386			t.Fatal(err)
387		}
388	
389		// 提交一份内容标识相同的合法报告（直接书写 U+FFFD）：已有归档字符损坏，
390		// 保存必须失败，而不是把损坏文件当作“同标识已保存”。
391		again := oneRuleCharReport("反例：�重入")
392		again.ReportID = id
393		if err := SaveReport(dir, again); err == nil {
394			t.Fatal("a character-corrupt existing archive must not count as a successful save")
395		} else {
396			var ec errCorrupt
397			if !errors.As(err, &ec) {
398				t.Fatalf("expected errCorrupt, got %T: %v", err, err)
399			}
400			if !strings.Contains(err.Error(), id) || !strings.Contains(err.Error(), "surrogate") {
401				t.Fatalf("error must name the report id and the surrogate: %v", err)
402			}
403		}
404		after, err := os.ReadFile(path)
405		if err != nil {
406			t.Fatalf("corrupt archive must be kept: %v", err)
407		}
408		if string(after) != string(before) {
409			t.Fatal("failed save must leave the corrupt archive untouched")
410		}
411	}
412	
413	// 并发落盘竞争中“抢先出现”的归档若字符损坏，同样按损坏失败并保留原文件。
414	func TestSaveReportRaceCharacterCorruptFileKept(t *testing.T) {
415		dir := t.TempDir()
416		legal := oneRuleCharReport("反例：�重入")
417		legal.ReportID = ReportID(legal)
418		data, err := json.Marshal(legal)
419		if err != nil {
420			t.Fatal(err)
421		}
422		corruptDoc := strings.ReplaceAll(string(data), string(replacementCharBytes), `\uD800`)
423		finalPath := filepath.Join(dir, legal.ReportID+".json")
424		saveReportHook = func(string) {
425			os.WriteFile(finalPath, []byte(corruptDoc), 0o644)
426		}
427		defer func() { saveReportHook = nil }()
428	
429		if err := SaveReport(dir, legal); err == nil {
430			t.Fatal("a racing character-corrupt archive must fail the save")
431		} else {
432			var ec errCorrupt
433			if !errors.As(err, &ec) {
434				t.Fatalf("expected errCorrupt, got %T: %v", err, err)
435			}
436		}
437		kept, _ := os.ReadFile(finalPath)
438		if string(kept) != corruptDoc {
439			t.Fatal("the character-corrupt racing archive must be kept, not overwritten")
440		}
441	}
442	
443	// --- 合法字符继续正常读取，说明与证据保留解码后的原文 ---
444	
445	func TestLoadReportLegalCharactersPreserved(t *testing.T) {
446		const note = "  反例：攻击者可在 withdraw 中重入\n第二行证据  "
447		dir := t.TempDir()
448		id := writeReportWithFreshID(t, dir, oneRuleCharReport(note))
449		loaded, err := LoadReport(dir, id)
450		if err != nil {
451			t.Fatalf("legal CJK/space/newline report must load: %v", err)
452		}
453		if loaded.Rules[0].Note != note || loaded.Findings[0].Evidence != note {
454			t.Fatalf("decoded text must be preserved:\n note=%q\n evidence=%q\nwant %q",
455				loaded.Rules[0].Note, loaded.Findings[0].Evidence, note)
456		}
457	}
458	
459	// 正确成对的代理转义与直接书写的同一字符读出后完全一致，标识也相同。
460	func TestLoadReportPairedEscapeEqualsLiteralCharacter(t *testing.T) {
461		dir := t.TempDir()
462		r := oneRuleCharReport("证据：😀 重入\n第二行  ")
463		wantID := ReportID(r)
464		emoji := []byte{0xF0, 0x9F, 0x98, 0x80}
465		id := writeVariantArchiveText(t, dir, r, func(doc string) string {
466			return strings.ReplaceAll(doc, string(emoji), `\uD83D\uDE00`)
467		})
468		if id != wantID {
469			t.Fatalf("paired escapes decode to the same report id, got %s want %s", id, wantID)
470		}
471		loaded, err := LoadReport(dir, id)
472		if err != nil {
473			t.Fatalf("paired surrogate escapes are legal and must load: %v", err)
474		}
475		want := "证据：😀 重入\n第二行  "
476		if loaded.Rules[0].Note != want || loaded.Findings[0].Evidence != want {
477			t.Fatalf("decoded text = %q / %q, want %q", loaded.Rules[0].Note, loaded.Findings[0].Evidence, want)
478		}
479	}
480	
481	// 原文中合法存在的 U+FFFD 只是普通字符，读取时原样保留。
482	func TestLoadReportLiteralReplacementCharPreserved(t *testing.T) {
483		dir := t.TempDir()
484		note := "原有替换字符 � 保留"
485		id := writeReportWithFreshID(t, dir, oneRuleCharReport(note))
486		loaded, err := LoadReport(dir, id)
487		if err != nil {
488			t.Fatalf("a literal U+FFFD is ordinary legal content: %v", err)
489		}
490		if loaded.Rules[0].Note != note || loaded.Findings[0].Evidence != note {
491			t.Fatalf("literal U+FFFD must be preserved: %q / %q", loaded.Rules[0].Note, loaded.Findings[0].Evidence)
492		}
493	}
494	
495	// “转义反斜线后接 uD800”只是普通文本，不得被误判成代理转义。
496	func TestLoadReportEscapedBackslashFollowedBySurrogateTextAccepted(t *testing.T) {
497		dir := t.TempDir()
498		note := `路径 C:\uD800\note`
499		id := writeReportWithFreshID(t, dir, oneRuleCharReport(note))
500		loaded, err := LoadReport(dir, id)
501		if err != nil {
502			t.Fatalf("an escaped backslash before uD800 text is ordinary content: %v", err)
503		}
504		if loaded.Rules[0].Note != note || loaded.Findings[0].Evidence != note {
505			t.Fatalf("ordinary text must be preserved verbatim: %q / %q",
506				loaded.Rules[0].Note, loaded.Findings[0].Evidence)
507		}
508	}
