func TestSaveReportInvalidUTF8TopAndArtifactFieldsRejected(t *testing.T) {
	base := func() Report {
		r := oneRuleCharReport("counterexample: x")
		r.ReportID = ReportID(r)
		return r
	}
	for _, tc := range []struct {
		name   string
