				legalRule("r-bad", StatusDefect, "反例 x"),
				legalRule("r-none", StatusUnchecked, ""),
			},
			Findings: []ReportFinding{
				{ArtifactHash: hash, RuleID: "r-bad", Version: "1", Severity: "high",
					Invariant: "inv-r-bad", Evidence: "反例 x"},
			},
		}
	}
	cases := []struct {
		name  string
